import{_ as e,a as r,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Rust FFI诊断：从符号到生命周期","description":"区分FFI符号链接、动态库加载、无效输入、回调寿命和panic诊断阶段。","frontmatter":{"title":"Rust FFI诊断：从符号到生命周期","description":"区分FFI符号链接、动态库加载、无效输入、回调寿命和panic诊断阶段。","showdocs":{"topics":[{"id":"rust","title":"Rust","link":"/topics/rust/"}],"kind":"排错","scope":"general","audience":"general","group":"语言与开发","seriesTitle":"Rust FFI：C宿主、所有权与回调边界","summary":"区分FFI符号链接、动态库加载、无效输入、回调寿命和panic诊断阶段。","status":"active","related":[{"title":"Rust 操作与命令","link":"/programming/rust/plus/ecosystem/rust-general-general","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 安装命令工具与发布软件包","link":"/programming/rust/plus/ecosystem/rust-general-general-part-04","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 编译、运行、测试与基准测量至阅读文档与命令帮助","link":"/programming/rust/plus/ecosystem/rust-general-general-part-03","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 查看、安装与更新 Rust 工具链至创建和定位 Cargo 项目","link":"/programming/rust/plus/ecosystem/rust-general-general-part-01","kind":"排错","scope":"general","audience":"general"},{"title":"Rust 操作与命令 · 选择依赖、更新锁文件与准备离线构建至格式化、静态检查与自动修复","link":"/programming/rust/plus/ecosystem/rust-general-general-part-02","kind":"排错","scope":"general","audience":"general"}],"prev":{"text":"Rust FFI完整项目：C宿主与同步回调","link":"/programming/rust/plus/practice/ffi-application"},"next":{"text":"Rust 过程宏：接口选择、展开与诊断责任","link":"/programming/rust/procedural-macros"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Rust FFI完整项目：C宿主与同步回调","link":"/programming/rust/plus/practice/ffi-application"},"next":{"text":"Rust 过程宏：接口选择、展开与诊断责任","link":"/programming/rust/procedural-macros"}},"headers":[],"relativePath":"programming/rust/plus/troubleshooting/ffi-diagnostics.md","filePath":"programming/rust/plus/troubleshooting/ffi-diagnostics.md"}'),i={name:"programming/rust/plus/troubleshooting/ffi-diagnostics.md"};function s(l,a,o,p,u,c){return r(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="rust-ffi诊断-从符号到生命周期" tabindex="-1">Rust FFI诊断：从符号到生命周期 <a class="header-anchor" href="#rust-ffi诊断-从符号到生命周期" aria-label="Permalink to &quot;Rust FFI诊断：从符号到生命周期&quot;">​</a></h1><p>先找到执行抵达的最后一步：链接器找到符号，加载器找到库，然后才有机会检查调用参数。若宿主已输出错误码，前两步在这次运行中已经成功，继续检查参数、状态或生存期。</p><h2 id="missing-symbol" tabindex="-1">找不到导出符号 <a class="header-anchor" href="#missing-symbol" aria-label="Permalink to &quot;找不到导出符号 {#missing-symbol}&quot;">​</a></h2><p>Rust FFI的undefined reference诊断先核对导出符号和库类型：Rust需要C ABI与固定符号名，C声明需和头文件一致，链接器还必须实际读取正确库。找到文件不等于找到符号；拼写、目标架构和MSVC导入库都会影响结果。先核查Cargo产物目录和CMake的RUST_TARGET_DIR，再由读者使用目标平台符号工具查看导出，不能随意添加no_mangle掩盖签名错误。</p><p>C++宿主漏写extern C可能导致名称修饰；本例头文件已经包含保护。静态链接的依赖和库顺序问题与DLL加载失败不同，追加运行PATH无法修复链接阶段undefined reference。即便同名符号成功链接，错误参数类型也可能在调用时破坏状态。</p><h2 id="loader-path" tabindex="-1">DLL和共享库加载失败 <a class="header-anchor" href="#loader-path" aria-label="Permalink to &quot;DLL和共享库加载失败 {#loader-path}&quot;">​</a></h2><p>Rust FFI的动态库加载失败诊断区分链接期导入库和运行期动态库：Windows需要DLL位于受控搜索位置，Unix需要正确的RPATH或加载路径。当前CMake只提供构建目录可用的部署安排，复制exe而遗漏库会失败。先核对实际产物、位数和依赖库，再检查加载路径；不要将陌生下载目录永久加入全局PATH。</p><p>macOS的动态库安装名、Linux的依赖搜索和Windows的DLL搜索机制并不相同。交叉构建还需相应C工具链与目标系统库，本机C编译器不能自动链接其他架构的Rust产物。staticlib也不能通过重命名变成动态库。</p><h2 id="invalid-input" tabindex="-1">非法UTF8与崩溃区别 <a class="header-anchor" href="#invalid-input" aria-label="Permalink to &quot;非法UTF8与崩溃区别 {#invalid-input}&quot;">​</a></h2><p>Rust FFI的非法UTF8诊断只适用于有效可读缓冲区，字节0xff会返回UTF8错误码；悬垂指针、错误长度或错误句柄可能在编码校验之前已触发UB。null判断不验证可读性，from_raw_parts也不探测分配边界。遇到崩溃应追踪分配、长度来源、借用期间写入和释放顺序，不能把catch_unwind当访问违规处理器。</p><p>本例接受null与零长度并绕开原始切片创建；若把代码改为对null直接from_raw_parts，空输入也违反函数前提。地址合法但长度超isize上界会返回ARGUMENT；地址可读却长度谎报仍是宿主责任。不要用随机指针生成测试声称验证了安全性。</p><h2 id="callback-crash" tabindex="-1">回调后崩溃与重复释放 <a class="header-anchor" href="#callback-crash" aria-label="Permalink to &quot;回调后崩溃与重复释放 {#callback-crash}&quot;">​</a></h2><p>Rust FFI的回调后崩溃诊断应核对context寿命、标签借用和释放次数；同步回调只保证调用返回前借用，保存标签地址仍可能悬垂。若回调销毁同一句柄或重入同一句柄，就违反独占协议；如果外部线程并发free，也无法靠函数内null判断保护。应从所有指针副本和库卸载顺序还原事件。</p><p>本例Host在main栈中直到返回，且没有异步工作；若修改为保存context，就必须同时增加停止、等待在途回调和注销协议。使用调试器或内存检测工具应由读者另行运行，静态阅读无法确认实际调度和内存安全。</p><h2 id="panic-diagnosis" tabindex="-1">panic错误与验证边界 <a class="header-anchor" href="#panic-diagnosis" aria-label="Permalink to &quot;panic错误与验证边界 {#panic-diagnosis}&quot;">​</a></h2><p>Rust FFI的PANIC错误诊断要求停止复用句柄并检查panic配置，因为catch_unwind只覆盖unwind路径，不覆盖abort或外国异常。看到panic hook输出并不自动说明展开已穿过C；需要结合返回码和终止行为判断。PANIC不承诺回滚，正常ARGUMENT/UTF8/OVERFLOW才有不修改状态的契约。</p><p>在 Linux x86_64 的宿主检查中，非法 UTF-8 返回 2，溢出返回 3；随后成功的更新回调总和为 5。两项输入错误都能恢复。要定位真实 panic 则要同时看构建的 panic 策略、返回码和进程是否存活；当前宿主未触发该分支。</p><h2 id="练习-给诊断排序" tabindex="-1">练习：给诊断排序 <a class="header-anchor" href="#练习-给诊断排序" aria-label="Permalink to &quot;练习：给诊断排序&quot;">​</a></h2><p>Windows宿主在链接成功后提示找不到DLL，开发者想改Rust函数的参数类型。列出先检查的三项，并解释改签名为何无助于当前阶段。</p><details><summary>参考解答</summary><p>先检查宿主旁是否存在对应DLL、DLL与exe是否同架构、DLL依赖是否可加载。参数类型影响调用阶段，无法使加载器找到文件；修改签名还可能破坏已经匹配的头文件。先修部署，再核对返回码和回调预期，每个阶段保留自己的证据。</p></details><h2 id="官方依据" tabindex="-1">官方依据 <a class="header-anchor" href="#官方依据" aria-label="Permalink to &quot;官方依据&quot;">​</a></h2><p><a href="https://doc.rust-lang.org/nomicon/ffi.html" target="_blank" rel="noopener noreferrer">Nomicon FFI</a>、<a href="https://doc.rust-lang.org/std/slice/fn.from_raw_parts.html" target="_blank" rel="noopener noreferrer">切片原始指针前提</a>、<a href="https://doc.rust-lang.org/std/panic/fn.catch_unwind.html" target="_blank" rel="noopener noreferrer">panic捕获限制</a>。涉及平台加载器时应结合所用系统的原始文档继续核查，本文没有冒称实测部署。</p>',22)])])}const m=e(i,[["render",s]]);export{g as __pageData,m as default};
